import numpy as np
from scipy import stats
from collections import defaultdict

MAX_DRIVERS = 4

def design(feats):
    if len(feats.ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for correlation-based near-duplicates
    corr_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                corr_pairs.add((min(fid1,fid2), max(fid1,fid2)))

    # Filter out near-duplicates
    unique_ids = []
    seen = set()
    for fid in feats.ids:
        if any(fid in pair for pair in corr_pairs):
            # Check if this feature is part of a correlated pair
            is_duplicate = False
            for pair in corr_pairs:
                if fid in pair:
                    # Only add the first one in the pair to avoid duplicates
                    if pair[0] not in seen:
                        unique_ids.append(pair[0])
                        seen.add(pair[0])
                    is_duplicate = True
                    break
            if not is_duplicate and fid not in seen:
                unique_ids.append(fid)
                seen.add(fid)
        else:
            if fid not in seen:
                unique_ids.append(fid)
                seen.add(fid)

    # Compute effect sizes using t-test
    effects = {}
    for i, fid in enumerate(unique_ids):
        x = feats.x[:, feats.column(fid)]
        y = feats.y
        mean_y1 = np.mean(x[y==1])
        mean_y0 = np.mean(x[y==0])
        effects[fid] = mean_y1 - mean_y0

    # Sort by absolute effect size
    sorted_effects = sorted(effects.items(), key=lambda x: abs(x[1]), reverse=True)

    # Test for association with outcome in each stratum
    stratum_results = {}
    for stratum in set(feats.stratum):
        mask = [s == stratum for s in feats.stratum]
        stratum_x = feats.x[mask]
        stratum_y = feats.y[mask]

        stratum_results[stratum] = {}
        for fid, _ in sorted_effects[:10]:  # Limit to top 10 for speed
            col_idx = feats.column(fid)
            x = stratum_x[:, col_idx]
            t_stat, p_val = stats.ttest_ind(x[stratum_y==1], x[stratum_y==0], equal_var=False)
            stratum_results[stratum][fid] = (t_stat, p_val)

    # Determine which features show consistent associations across strata
    drivers = []
    for fid, _ in sorted_effects:
        # Check if feature shows significant effect in all strata
        valid_strata = 0
        total_strata = len(set(feats.stratum))
        for stratum in set(feats.stratum):
            if fid in stratum_results[stratum]:
                t_stat, p_val = stratum_results[stratum][fid]
                if p_val < 0.05:  # Significant
                    valid_strata += 1

        # If feature shows effect in > 50% of strata, consider it
        if valid_strata / total_strata > 0.5:
            drivers.append(fid)
            if len(drivers) >= MAX_DRIVERS:
                break

    # If we have no drivers, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select features for regression
    columns = tuple(unique_ids[:10])  # Top 10 features by effect size

    # Create product terms for top features
    products = []
    for i, fid1 in enumerate(columns[:5]):
        for j, fid2 in enumerate(columns[i+1:5]):
            products.append((fid1, fid2))

    # Weighted score based on effect sizes
    loadings = {}
    for fid in columns:
        loadings[fid] = effects[fid]

    return Design(drivers=tuple(drivers), columns=columns, products=tuple(products), loadings=loadings)
